import{_ as a,a as r,b as o,c as s,d as i,e as l,f as n,g as h,h as c}from"./chunks/b49b5672a450fb04b394.BHV6UKBl.js";import{_ as m,C as d,o as u,c as _,j as t,a as f,E as g,a5 as b}from"./chunks/framework.DNkHA0lr.js";const A=JSON.parse('{"title":"21世纪最伟大的技能（顶尖1%的人都在利用它）","description":"","frontmatter":{"title":"21世纪最伟大的技能（顶尖1%的人都在利用它）","originalTitle":"The Greatest Skill Of The 21st Century (The Top 1% Exploit This)","date":"2023-10-06","originalUrl":"https://thedankoe.com/letters/the-most-important-skill-of-the-21st-century-only-1-use-it/","minutes":11,"sourceHash":"ebbf905effef7d5462501791e5b00907d98c6833ff1dd3c119f7c5d83073d53a","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-most-important-skill-of-the-21st-century-only-1-use-it/"}]]},"headers":[],"relativePath":"letters/the-most-important-skill-of-the-21st-century-only-1-use-it.md","filePath":"letters/the-most-important-skill-of-the-21st-century-only-1-use-it.md"}'),k={name:"letters/the-most-important-skill-of-the-21st-century-only-1-use-it.md"};function q(P,p,x,T,y,w){const e=d("ArticleMeta");return u(),_("div",null,[p[0]||(p[0]=t("h1",{id:"_21世纪最伟大的技能-顶尖1-的人都在利用它",tabindex:"-1"},[f("21世纪最伟大的技能（顶尖1%的人都在利用它） "),t("a",{class:"header-anchor",href:"#_21世纪最伟大的技能-顶尖1-的人都在利用它","aria-label":'Permalink to "21世纪最伟大的技能（顶尖1%的人都在利用它）"'},"​")],-1)),g(e),p[1]||(p[1]=b('<p><a href="https://www.youtube.com/embed/j5S5a7_pk60?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我说实话。</p><p>我和<a href="https://twitter.com/iamjustincscott" target="_blank" rel="noreferrer">Justin Scott</a>正在进行一场时事通讯写作比赛。</p><p>我们计划在7天内写完7篇时事通讯，以便存点底稿。</p><p>我甚至更进一步，每天都在录制，总共录制了7个YouTube视频。</p><p>今天的写作碰上了一个大忙天，我正在准备Sprint课程辅导的电话会议。</p><p>所以……我直接从<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>课程里复制粘贴了这篇文章（这甚至不到里面内容的1%）。</p><p>在我眼里，它是你能掌握的最重要的技能之一：<strong>有说服力的沟通。</strong></p><p>只有这样，人们才会真正分享你的文章（这意味着你在社交媒体上能真正获得增长）。</p><p>作为福利，我附上了一个PDF下载链接（无需填写邮箱），里面包含了我们在这封信中讨论的内容。</p><p><a href="https://www.dropbox.com/scl/fi/nhvzkqzbzlp6ro6ocb8a4/ContentPresentation.pdf?rlkey=8kpb8t3wgc21wu9acqg33c80v&amp;dl=0" target="_blank" rel="noreferrer">在新标签页中打开这个PDF，以免找不到了。</a></p><p>我强烈建议你在撰写内容时把它打开。</p><p>它包含了提升互动率的“Koe氏十诫”以及32个你可以模仿的帖子结构——这是我个人的灵感库。</p><p>让我们开始吧：</p><p><strong>人们不会记住你说了什么，他们只会记住你给他们带来的感受。</strong></p><p>这句话值得重复一遍：</p><p><em>人类是感性的动物，而非理性的。</em></p><p>99%的人还没有修炼到能够摆脱——或者控制——自己自我意识（ego）的地步。</p><p>这正是捕捉和保持注意力的基础。</p><p>戳中读者的自我意识。</p><p>喂养它 = 让他们感觉“良好”。</p><p>饿着它 = 让他们感觉“糟糕”。</p><p>如果你能带领人们踏上一段充满爱、恨、兴奋、欺骗、平静等情绪的旅程，并且最终为他们的生活带来益处——你就掌握了内容创作的艺术。</p><p>生活就是故事。</p><p>歌曲也是故事（Uni-verse宇宙，意即一首歌）。</p><p>建筑、音乐、植物生命以及其他一切事物，都遵循着高潮/低谷、创造/毁灭、生长/死亡等宇宙法则。</p><p>人类通过故事来理解世界。</p><p>你的工作就是运用语言的力量，让人们<em>感受</em>到一些东西。</p><p>故事模仿了情绪自然的高低起伏。</p><p>在我们开始之前：</p><p>《专注的艺术》（The Art Of Focus，我的书）现已<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">开放预购。</a></p><p>（这不是一次普通的图书发布，它很贵，而且贵得有理。）</p><p>平装本将在2000本纪念版售罄后发布。</p><h2 id="dan捕获注意力的-koe氏十诫" tabindex="-1">Dan捕获注意力的“Koe氏十诫” <a class="header-anchor" href="#dan捕获注意力的-koe氏十诫" aria-label="Permalink to &quot;Dan捕获注意力的“Koe氏十诫”&quot;">​</a></h2><p>当你刷社交媒体或者只是在阅读日常内容时——试着留意这些正在被使用的策略。这是将这些信息巩固在你脑海中的最佳方式。注意你的注意力何时被捕捉到，并问一问“为什么”。</p><p>捕捉注意力的方法有很多。我发现以下这些是最可复制且最实用的（第8点最重要）：</p><h3 id="_1-具体的数字" tabindex="-1">1) 具体的数字 <a class="header-anchor" href="#_1-具体的数字" aria-label="Permalink to &quot;1) 具体的数字&quot;">​</a></h3><p>在你的钩子、标题或推文中使用数字，会让人们停下来看一看这些数字与什么有关。</p><p>它们可以是以下形式：</p><ul><li><strong>统计数据</strong> ——“地球上有70亿人”</li><li><strong>金额</strong> ——“苹果新款1175美元的iPhone有这个新功能”</li><li><strong>指标</strong> ——“我发送了322封冷邮件”或“在293天后……”</li><li><strong>列表</strong> ——“阻碍你的7个坏习惯……”</li></ul><p>数字越具体，就越能吸引人们的注意力。</p><p>如果你做不到非常具体，也没关系。别给自己太大压力。</p><p>这是我的一个例子，它是促使许多人加入Digital Economics（我的课程）的决定性因素：</p><p><img src="'+a+'" alt=""></p><h3 id="_2-模式中断" tabindex="-1">2) 模式中断 <a class="header-anchor" href="#_2-模式中断" aria-label="Permalink to &quot;2) 模式中断&quot;">​</a></h3><p>模式中断是指打破人们常规条件反射模式的事物。</p><p>如果有人在刷X（原Twitter），并且习惯了看大量的政治评论，那么一条排版精美的列表推文就会让他们停止划动。</p><p>这个列表中的大多数东西都属于模式中断。</p><h3 id="_3-负面偏见" tabindex="-1">3) 负面偏见 <a class="header-anchor" href="#_3-负面偏见" aria-label="Permalink to &quot;3) 负面偏见&quot;">​</a></h3><p>人脑天生就容易记住并关注负面事物。</p><p>这并不意味着你必须一直消极负能量。</p><p>它的意思是，你需要使用词语的负面形式。</p><p>如果你正在表达积极的事情，但用负面的形式能更好地阐明观点，那就用负面形式。</p><p>“你将会取得伟大的成就。”</p><p>相比于：</p><p>“你再也不会跌入谷底了。”</p><p>第二种最有力量。我们会记住负面的东西。这是许多人生活中最能产生共鸣的一面。</p><p>它仍然可以传达积极的信息，同时利用读者的负面偏见。</p><h3 id="_4-圈层点名" tabindex="-1">4) 圈层点名 <a class="header-anchor" href="#_4-圈层点名" aria-label="Permalink to &quot;4) 圈层点名&quot;">​</a></h3><p>这很简单，直接点出你在和哪个特定人群说话。</p><ul><li>如果你正处于20多岁……</li><li>呼叫所有的创作者、教练和自由职业者！</li><li>父亲是给人类的礼物……</li></ul><p>即使你的受众不属于你所点名的特定群体，这也能让他们“站队”，并将自己与你所说的话进行比较。</p><p>几天前我谈到了健美运动员。即使人们不认为自己是健美运动员，这也描绘出了一幅他们能够代入的画面：</p><p><img src="'+r+'" alt=""></p><p>如果有人谈论为人父的感受，我仍然能产生共鸣，因为我总有一天也会成为父亲。我依然会关注并接受这个建议。</p><p>这在进行推广时也很有效。你可以明确点出推广的对象是谁，并描绘出他们正在挣扎的痛点画面。</p><h3 id="_5-痛点点名" tabindex="-1">5) 痛点点名 <a class="header-anchor" href="#_5-痛点点名" aria-label="Permalink to &quot;5) 痛点点名&quot;">​</a></h3><p>点出人们正在经历的痛苦或问题，也会让他们对帖子产生共鸣。</p><p>大多数人在一生中都会遇到和其他人一样的问题或痛苦。</p><p>如果你能准确地描述这种感觉，你就能毫不费力地抓住人们的注意力。</p><p>你不需要说得绝对精准。只要描述出痛点，人们就会试图将自己的经历代入其中。如果他们能产生共鸣，就会产生互动。</p><p>这里有一个例子，点出了像“感觉糟糕”这样简单的痛点：</p><p><img src="'+o+'" alt=""></p><h3 id="_6-潜在收益" tabindex="-1">6) 潜在收益 <a class="header-anchor" href="#_6-潜在收益" aria-label="Permalink to &quot;6) 潜在收益&quot;">​</a></h3><p>与点出痛点正好相反。还是那句话，痛点和收益。你的大脑需要以痛点和收益来思考。这就是你写的任何“是什么”或“怎么做”背后的那个独特的“为什么”。</p><h3 id="_7-社交证明" tabindex="-1">7) 社交证明 <a class="header-anchor" href="#_7-社交证明" aria-label="Permalink to &quot;7) 社交证明&quot;">​</a></h3><p>同样，这具有权威性，并暗示了信息差的存在。</p><p>当你展示你的成果或资历时，人们会自动默认你比他们懂得多。他们会更认真地对待你的内容，并通过阅读来寻找他们“缺失”的信息。</p><p>当这不被视为一种“炫耀”时，效果会好上100倍。</p><p>Justin Welsh是这方面当之无愧的王者：</p><p><img src="'+s+'" alt=""></p><p>用社交证明来阐明你想要表达的观点。</p><h3 id="_8-自信与信念" tabindex="-1">8) 自信与信念 <a class="header-anchor" href="#_8-自信与信念" aria-label="Permalink to &quot;8) 自信与信念&quot;">​</a></h3><p><em><strong>这是目前为止最重要的一点。</strong></em></p><p>单凭自信，你就能创作出极具影响力的帖子——它会让其他吸引注意力的要素水到渠成。</p><p>就此时此刻而言，关于你的目标、愿景、信仰、价值观以及构成你现实视角的一切事物，你都是对的。</p><p>你的工作就是对自己的信念抱有自信和坚定，并拿出可信或清晰的论点来支持它们（如果必须的话）。</p><p>每个人上社交媒体，都是为了听到别人用自信的方式告诉他们该怎么做。没有人对自己的行为、选择和信仰有绝对的安全感。他们正在寻找那个能自信地给予他们肯定、并给他们行动方向感的人。</p><p>能让你听起来更自信的工具：</p><ul><li>消除暗示不确定的词语</li><li>尽可能用绝对的口吻说话</li><li>夸大你的观点以注入能量</li></ul><p>当然，不要为了互动率而滥用这些技巧。</p><p>与其说：</p><p><em>“如果有些人能提升一下他们的技能，也许是明智的。”</em></p><p>不如说：</p><p><em>“地球上的每个人都必须提升自己的技能，这是至关重要的。”</em></p><p>仅仅因为充满自信，文字的流露就会更顺畅，写出来的东西也更具冲击力。</p><p>然后我可以用统计数据，或者我脑海中更具创造力的火力来支持这个论点。</p><p>下面这个例子，展示了我在表达时的自信：</p><p><img src="'+i+'" alt=""></p><p>这条推文被一份大型时事通讯收录，并引发了大量争议。</p><p>人们在争论它到底是不是“最伟大”的技能。有些人则在提出他们心中最伟大的技能是什么。</p><p>这促使人们发表评论和引用转发，从而带来了更多的互动和曝光。</p><p>我是在快速执行完一个想法的那一刻写下这条推文的。那个举动给了我极大的快乐，所以我想和别人分享这份快乐。这奏效了。</p><p>它100%正确吗？并非如此。</p><p>当我结合个人经历、通过我自己的视角写下它时，它是100%正确的吗？</p><p>是的。在当时，我百分之百地确信那就是最伟大的技能。</p><p>随后我在回复中补充了更多细微的观点。如果我在原推文中就加上这些克制的细节，它的效果就不会那么好，也就失去了被大型时事通讯收录的机会。</p><p><strong>你</strong>想要吸引的人，绝不是那些“喷”你作品的人。</p><p>这里还有另一个——稍微极端一点的——例子。你能感觉到那种鸡血满满又务实的能量“溢出屏幕”吗？</p><p><img src="'+l+'" alt=""></p><p>顺便说一句，这类高能量的建议帖能吸一大波粉。</p><p>总而言之——对你所说的话要有一点信念感。这不是什么需要被训练的技能。它只关乎于用最具影响力的方式把字写出来。领导者在传达观点时，从不拐弯抹角。</p><h3 id="_9-主动语态" tabindex="-1">9) 主动语态 <a class="header-anchor" href="#_9-主动语态" aria-label="Permalink to &quot;9) 主动语态&quot;">​</a></h3><p>主动语态意味着有故事发生。它能让人们更轻松地代入你所说的话。</p><p>被动语态通常很无聊，而且太早泄露了“迷你故事”的悬念。它没有任何能让人产生“接下来发生了什么”的期待感。</p><p>当你练习写帖子时，去找一篇关于主动语态的文章看一看，并用它来修改你的文字，直到你掌握窍门。</p><p>这也有助于让你看起来更加自信。</p><h3 id="_10-警告与劝诫" tabindex="-1">10) 警告与劝诫 <a class="header-anchor" href="#_10-警告与劝诫" aria-label="Permalink to &quot;10) 警告与劝诫&quot;">​</a></h3><p>当人们试图实现某个目标时，他们需要注意什么？</p><p>当他们努力达到你现在的成就时，你能否警告他们会遭遇什么？</p><p>当你进行每周复盘，或者仅仅是反思生活时，你能够帮人们避开哪些路障？</p><p>这条推文就是最好的证明。我击中了多巴胺这样的热门话题，并警告了他们另一个热门话题（然后用自信的语气收尾）。</p><p>这引发了极大的争议，但我有研究来支持这个观点，并且在回复中提供了克制的细节，以此与我的受众建立更深层的连接：</p><p><img src="'+n+'" alt=""></p><h2 id="是什么保持了注意力" tabindex="-1">是什么保持了注意力？ <a class="header-anchor" href="#是什么保持了注意力" aria-label="Permalink to &quot;是什么保持了注意力？&quot;">​</a></h2><p>一旦好奇心的循环被打开，大脑就会觉得自己有义务去弄清楚故事的结局。</p><p>这正是保持注意力的关键——讲述一个引人入胜的故事。</p><p>故事是隐喻、概念、视角和经历的层层叠加，带领人们踏上一段旅程。</p><p>人们想要了解整个故事。他们想知道在任何给定事件（从吸引注意力开始）的前、中、后究竟发生了什么。</p><p>在维持注意力方面，有两件事需要牢记：</p><h3 id="_1-结构" tabindex="-1">1) 结构 <a class="header-anchor" href="#_1-结构" aria-label="Permalink to &quot;1) 结构&quot;">​</a></h3><p>我们已经不在高中了。长篇大论、过于专业的段落毫无意义，还会降低可读性。尤其是在 X（原推特）上——人们登录这个平台就是为了逃离职场世界。</p><p>你该如何改善所有内容的结构？</p><ul><li><strong>要点列表（Bullet lists）</strong> —— 使用数字、项目符号和其他策略来帮你拆解你要说的话。这些列表本身就构成了一个“故事”。</li><li><strong>换行（Line breaks）</strong> —— 尽可能多地使用换行，但别为了换行而换行。发挥点创意。用换行来强调特定的句子，并让你的写作如流水般顺畅。</li><li><strong>开篇简短精炼（Starting short and concise）</strong> —— 在内容开头使用较短的句子或段落。用短促有力的陈述抓住注意力，然后再放开手脚，在句子的起承转合上发挥创意。</li><li><strong>拆分句子（Break apart sentences）</strong> —— 多用括号和破折号“—”来代替逗号。这个句子太长了（直到我让人们想知道这个括号里到底写了什么）。</li></ul><p>以下是将上述所有技巧融于一个钩子（hook）的示例：</p><p><img src="'+h+'" alt=""></p><h3 id="_2-新颖的视角" tabindex="-1">2) 新颖的视角 <a class="header-anchor" href="#_2-新颖的视角" aria-label="Permalink to &quot;2) 新颖的视角&quot;">​</a></h3><p>这要求你从书籍、播客或其他能够为某些观点提供更多细微差别的长内容中获取大部分的想法。</p><p>新奇感会提升大脑中的多巴胺水平。它能让一个被反复咀嚼的观点变得更加清晰明了。</p><p>如果你试图在 Twitter 上发展壮大，却把 Twitter 当作获取全部内容的唯一来源——你最终的视角很可能变得和别人一模一样。</p><p>比喻、个人经历，以及创造新概念，就是你实现这一目标的方法。</p><p>这将是我们未来模块的首要重点，所以现在先按兵不动（但请把这点记在心里，以便你在消费内容时能开始建立联系）。</p><p>我当时在读一篇文章，了解到一杯水如何能制造出一英亩的浓雾，然后我把这个概念应用到了我的一个子主题——正念（mindfulness）上。</p><p><img src="'+c+'" alt=""></p><p>内容的<em>消费</em>（或研究）很重要。尤其是书籍、有声读物、播客或文章。它们会为你提供截然不同的视角，让你更深入地探讨你热爱的话题。</p><h2 id="是什么创造了互动参与" tabindex="-1">是什么创造了互动参与？ <a class="header-anchor" href="#是什么创造了互动参与" aria-label="Permalink to &quot;是什么创造了互动参与？&quot;">​</a></h2><p>记住：<em><strong>人们不会记得你说了什么，他们只会记得你带给他们的感受。</strong></em></p><p>阿兰·瓦茨（Alan Watts）晚年可能是个酒鬼，还背叛过几任妻子——对此我保留个人意见——但他的作品永远地改变了我的人生。它给了我启发、清晰感，以及全新的人生观。</p><p>我也许能记住他的一些名言，但我之所以能记住，是因为它们带给我的那种通透感。那种在这个世上毫无忧虑的感觉。当我想再次体验这种感觉时，我就会播放一段阿兰·瓦茨的演讲。</p><p>而你，只不过是一条足以改变人生的信息的谦卑使者。</p><p><strong>1) 来自教育的感受。</strong></p><p>学到新知识或对生活中的某个方面有了更清晰的认知，会提升大脑中的多巴胺水平。</p><p>你可以通过新颖的视角、比喻、故事、个人经历以及生活中其他能帮助他人理解你所说内容的部分，来创造这种通透感。</p><p>你的工作是让特定的一群人觉得你说的“有道理”。</p><p>你的做法是：分享某些话题在你这里是如何说得通的。</p><p><strong>2) 来自启发的感受。</strong></p><p>启发不同于动机。</p><p>你在帮助人们自行将线索串联起来，赋予他们洞察力，从而自己做出决定并改变行为。</p><p>当人们觉得是自己想出答案时，他们会感觉很棒——但他们依然会将这种感觉归功于你。</p><p><strong>3) 来自娱乐的感受。</strong></p><p>你能抛出一个笑话、一个梗（meme）或者一个有趣的视角吗？</p><p>当你看电影时，你通过幽默、戏剧冲突、故事的走心部分以及点燃你激情的战斗场面获得了娱乐。</p><p>娱乐、教育和启发，是你内容的三个主要目标。</p><p>希望你喜欢这篇文章。</p><p>如果你想成为一名通过互联网掌控自己人生走向的数字写手，请在<a href="https://thedankoe.com/blog/category/digital-writing/" target="_blank" rel="noreferrer">数字写手系列（Digital Writer series）</a>中阅读更多内容。</p><p>Dan Koe</p><p>P.S. 《专注的艺术》（The Art Of Focus）已经开放预购。</p><p>包含精装实体书、全新升级的实体计划本、一枚纪念币、线下活动的邀请函、一个私密社区，等等。</p><p><a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">在此处抢购仅有的2000套之一。</a></p><hr><p><a href="/en/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',171))])}const C=m(k,[["render",q]]);export{A as __pageData,C as default};
